package com.hospital.smartqueue.doctor.infrastructure; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class DoctorDepartmentRepository { private final JdbcTemplate jdbc; public DoctorDepartmentRepository(JdbcTemplate j){jdbc=j;} public void add(UUID d,UUID p){jdbc.update("insert into doctor_departments(doctor_id,department_id) values (?,?)",d,p);} public List<UUID> doctors(UUID p){return jdbc.queryForList("select doctor_id from doctor_departments where department_id=?",UUID.class,p);} }
